import{_ as a,o,c as n,a2 as r}from"./chunks/framework.DZhUhjDB.js";const l=JSON.parse('{"title":"02 — Glosario de términos esenciales","description":"","frontmatter":{"title":"02 — Glosario de términos esenciales"},"headers":[],"relativePath":"modules/fundamentos/02-glosario.md","filePath":"modules/fundamentos/02-glosario.md","lastUpdated":1787330151000}'),t={name:"modules/fundamentos/02-glosario.md"};function s(i,e,d,p,c,u){return o(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="_02-—-glosario-de-terminos-esenciales" tabindex="-1">02 — Glosario de términos esenciales</h1><blockquote><p><strong>Cómo usar este archivo:</strong> No hace falta leerlo entero. Vuelve a él cada vez que un archivo nuevo use un término que no conoces. Está organizado por tema y, dentro de cada tema, alfabéticamente.</p></blockquote><blockquote><p>📖 Convenciones: términos en <strong>negrita</strong> son los más importantes; ↗ señala a otro término del glosario; 📘 a un archivo de la base; 📂 a una carpeta del repo.</p></blockquote><hr><h2 id="🔤-a–e" tabindex="-1">🔤 A–E</h2><p><strong>Ataque</strong> — Cualquier intento de comprometer la ↗ <strong>C</strong>onfidencialidad, ↗ <strong>I</strong>ntegridad o ↗ disponibilidad de un sistema.</p><p><strong>APT (Advanced Persistent Threat)</strong> — Atacante sofisticado (a menudo estatal) que entra, se queda y observa durante meses.</p><p><strong>Attack Surface</strong> — La &quot;superficie atacable&quot;: todos los puntos por donde un atacante podría entrar.</p><p><strong>Authentication</strong> — Probar quién eres (sabes algo, tienes algo, eres algo). Ver ↗ <strong>MFA</strong>.</p><p><strong>Authorization</strong> — Qué se te permite hacer una vez autenticado.</p><p><strong>Backdoor</strong> — Puerta trasera: acceso oculto que evita la autenticación normal.</p><p><strong>Blue Team</strong> — Equipo de defensa. Ver 📘 <a href="./01-que-es-ciberseguridad"><code>01-que-es-ciberseguridad.md</code></a>.</p><p><strong>Bug Bounty</strong> — Programa donde una empresa paga a hackers éticos por reportar vulnerabilidades.</p><p><strong>CIA Triad</strong> — Confidencialidad, Integridad, Disponibilidad (Availability). Los 3 pilares.</p><p><strong>CVE (Common Vulnerabilities and Exposures)</strong> — ID único para una vulnerabilidad pública. Ej: <code>CVE-2024-12345</code>.</p><p><strong>CVSS</strong> — Sistema de 0 a 10 para puntuar la gravedad de un ↗ <strong>CVE</strong>.</p><p><strong>CWE (Common Weakness Enumeration)</strong> — Categoría de debilidad de software (la &quot;familia&quot; del problema).</p><p><strong>DDoS (Distributed Denial of Service)</strong> — Tumbar un servicio enviándole tráfico desde miles de máquinas.</p><p><strong>DNS (Domain Name System)</strong> — La &quot;agenda&quot; de internet: traduce <code>google.com</code> a <code>142.250.190.78</code>.</p><p><strong>Endpoint</strong> — Cualquier dispositivo conectado: laptop, móvil, servidor, IoT.</p><p><strong>Enumeration</strong> — Fase del pentest donde recopilas usuarios, recursos, servicios de un objetivo.</p><p><strong>Exploit</strong> — Código que aprovecha una vulnerabilidad.</p><hr><h2 id="🔤-f–m" tabindex="-1">🔤 F–M</h2><p><strong>Firewall</strong> — Filtra el tráfico de red según reglas. Hay de hardware y de software.</p><p><strong>Forensics</strong> — Investigación post-incidente para entender qué pasó, cómo y cuándo.</p><p><strong>Hash</strong> — Función que convierte cualquier dato en una cadena fija de tamaño. Ej: SHA-256. Ver 📘 <a href="./05-criptografia-basica"><code>05-criptografia-basica.md</code></a>.</p><p><strong>Honeypot</strong> — Sistema señuelo: parece real pero sirve para detectar y estudiar atacantes.</p><p><strong>HTTP / HTTPS</strong> — Protocolo de la web. La S significa &quot;con TLS&quot; (cifrado).</p><p><strong>IDS / IPS</strong> — <em>Intrusion Detection / Prevention System</em>. Detecta o bloquea ataques.</p><p><strong>Incident</strong> — Un evento de seguridad confirmado que requiere respuesta.</p><p><strong>Ing Social (Ingeniería Social)</strong> — Engañar a personas para que revelen info o hagan algo. ↗ <strong>Phishing</strong>.</p><p><strong>IOC (Indicator of Compromise)</strong> — Huella que deja un ataque: IP, hash, dominio, patrón.</p><p><strong>IP (Internet Protocol)</strong> — La dirección numérica de cada dispositivo en una red. <code>192.168.1.1</code>.</p><p><strong>JWT</strong> — Token firmado para autenticación web sin estado.</p><p><strong>Kill Chain</strong> — Pasos típicos de un ataque: reconocimiento → arma → entrega → exploitation → instalación → command &amp; control → acciones.</p><p><strong>Lateral Movement</strong> — Una vez dentro, el atacante se mueve a otros sistemas de la misma red.</p><p><strong>Linux</strong> — Familia de sistemas operativos (Ubuntu, Debian, Kali, etc.) muy usada en servidores y seguridad.</p><p><strong>Malware</strong> — Software malicioso. Incluye virus, troyanos, ransomware, spyware.</p><p><strong>MFA (Multi-Factor Authentication)</strong> — Pedir 2+ pruebas de identidad. La MFA bloquea el 99% de los ataques de cuentas.</p><p><strong>MITM (Man in the Middle)</strong> — Atacante que intercepta comunicación entre dos partes.</p><hr><h2 id="🔤-n–s" tabindex="-1">🔤 N–S</h2><p><strong>Nmap</strong> — Escáner de puertos. La navaja suiza del reconocimiento. Ver 📘 <a href="./08-herramientas-esenciales"><code>08-herramientas-esenciales.md</code></a>.</p><p><strong>OSINT (Open Source Intelligence)</strong> — Recopilar info de fuentes públicas: redes sociales, leaks, DNS, etc.</p><p><strong>OWASP</strong> — Organización que mantiene el famoso <em>Top 10</em> de vulnerabilidades web. Ver 📘 <a href="./06-vulnerabilidades"><code>06-vulnerabilidades.md</code></a>.</p><p><strong>P0 / P1 / P2</strong> — Prioridades: P0 = crítico (cae producción), P1 = urgente, P2 = importante.</p><p><strong>Password Hashing</strong> — Guardar contraseñas como ↗ <strong>hash</strong> (no en texto plano).</p><p><strong>Patch</strong> — Actualización que corrige una vulnerabilidad.</p><p><strong>Pentest</strong> — Test de penetración autorizado. Buscar vulnerabilidades con permiso.</p><p><strong>Phishing</strong> — Email/mensaje fraudulento que imita a alguien legítimo. ↗ <strong>Ing Social</strong>.</p><p><strong>Port (puerto)</strong> — &quot;Puerta&quot; de un servicio en una máquina. HTTP=80, HTTPS=443, SSH=22.</p><p><strong>Privilege Escalation</strong> — Conseguir más permisos de los que deberías tener.</p><p><strong>Purple Team</strong> — Equipo mixto red + blue. Ver 📘 <a href="./01-que-es-ciberseguridad"><code>01-que-es-ciberseguridad.md</code></a>.</p><p><strong>Ransomware</strong> — ↗ <strong>Malware</strong> que cifra tus datos y pide rescate.</p><p><strong>Red Team</strong> — Equipo ofensivo. Ver 📘 <a href="./01-que-es-ciberseguridad"><code>01-que-es-ciberseguridad.md</code></a>.</p><p><strong>Reverse Shell</strong> — Conexión que la víctima abre hacia el atacante. Muy común post-exploit.</p><p><strong>Risk</strong> — Probabilidad × Impacto. Lo que tu jefe quiere ver cuando le pides presupuesto.</p><p><strong>SIEM</strong> — Sistema central que recoge logs y dispara alertas (Splunk, Elastic, Wazuh).</p><p><strong>SOC (Security Operations Center)</strong> — El equipo que vigila 24/7 con ayuda del SIEM.</p><p><strong>SQL Injection</strong> — Inyectar SQL en un input para manipular la base de datos. Ver 📘 <a href="./06-vulnerabilidades"><code>06-vulnerabilidades.md</code></a>.</p><p><strong>SSL/TLS</strong> — Protocolo que cifra las comunicaciones en internet. La S de HTTPS.</p><hr><h2 id="🔤-t–z" tabindex="-1">🔤 T–Z</h2><p><strong>Threat</strong> — Amenaza: algo que podría causar daño (un atacante, una tormenta, un bug).</p><p><strong>Threat Intelligence</strong> — Estudiar amenazas: quién ataca, cómo, por qué, qué busca.</p><p><strong>Threat Hunting</strong> — Buscar activamente atacantes que ya están dentro pero aún no se detectaron.</p><p><strong>Token</strong> — Cadena que prueba que estás autenticado, sin guardar sesión en servidor. Ver ↗ <strong>JWT</strong>.</p><p><strong>TTP (Tactics, Techniques, Procedures)</strong> — Patrones de un atacante. Lo modela MITRE ATT&amp;CK.</p><p><strong>Vulnerability</strong> — Debilidad que un atacante puede explotar.</p><p><strong>WAF (Web Application Firewall)</strong> — Firewall especializado en tráfico HTTP/HTTPS.</p><p><strong>Wireshark</strong> — Analizador de tráfico de red. Captura paquetes para analizarlos. Ver 📘 <a href="./08-herramientas-esenciales"><code>08-herramientas-esenciales.md</code></a>.</p><p><strong>XSS (Cross-Site Scripting)</strong> — Inyectar JS malicioso en una página web. Ver 📘 <a href="./06-vulnerabilidades"><code>06-vulnerabilidades.md</code></a>.</p><p><strong>Zero-Day</strong> — Vulnerabilidad recién descubierta para la que aún no hay parche.</p><hr><h2 id="📚-siglas-que-veras-mucho" tabindex="-1">📚 Siglas que verás mucho</h2><ul><li><strong>CTF</strong> — <em>Capture The Flag</em>: retos de hacking competitivo</li><li><strong>CSIRT / CERT</strong> — Equipos de respuesta a incidentes</li><li><strong>EDR / XDR</strong> — Endpoint / Extended Detection &amp; Response</li><li><strong>GRC</strong> — Governance, Risk, Compliance</li><li><strong>IAM</strong> — Identity &amp; Access Management</li><li><strong>IR</strong> — Incident Response</li><li><strong>MDM</strong> — Mobile Device Management</li><li><strong>NDR</strong> — Network Detection &amp; Response</li><li><strong>SOAR</strong> — Security Orchestration, Automation, Response</li><li><strong>VPN</strong> — Red privada virtual</li></ul><blockquote><p>📂 Las definiciones completas de cada rol están en <a href="./../01-CIBERSEGURIDAD/"><code>01-CIBERSEGURIDAD/</code></a> (37 subcarpetas).</p></blockquote><hr><blockquote><p>⏭️ <strong>Siguiente:</strong> <a href="./03-internet-y-redes"><code>03-internet-y-redes.md</code></a> — los conceptos mínimos de redes que necesitas.</p></blockquote>',80)])])}const m=a(t,[["render",s]]);export{l as __pageData,m as default};
